#!/usr/bin/env node
/**
 * Fetches the Can I Email dataset (MIT-licensed, https://www.caniemail.com)
 * and filters it down to CSS/HTML features where Outlook on Windows is
 * reported unsupported ("n") or partial/buggy ("a") for at least one
 * version, so we get one "gimmick" per real documented Outlook quirk.
 *
 * Output: gimmicks.json (checked in, reviewable, not regenerated by CI).
 */
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const DATA_URL = "https://www.caniemail.com/api/data.json";
const OUT_PATH = fileURLToPath(new URL("./gimmicks.json", import.meta.url));

// A support code like "n #3" -> "n". Codes: y (yes), n (no), a (partial/buggy), u (unknown).
function baseCode(code) {
  return code.trim().split(/\s/)[0];
}

async function main() {
  const res = await fetch(DATA_URL);
  if (!res.ok) {
    throw new Error(`Failed to fetch ${DATA_URL}: ${res.status} ${res.statusText}`);
  }
  const json = await res.json();

  const gimmicks = [];
  for (const feature of json.data) {
    if (feature.category !== "css" && feature.category !== "html") continue;

    const windows = feature.stats?.outlook?.windows;
    if (!windows) continue;

    const codesByVersion = Object.fromEntries(
      Object.entries(windows).map(([version, code]) => [version, baseCode(code)]),
    );
    const isGimmick = Object.values(codesByVersion).some((code) => code === "n" || code === "a");
    if (!isGimmick) continue;

    gimmicks.push({
      slug: feature.slug,
      title: feature.title,
      description: feature.description ?? null,
      category: feature.category,
      url: feature.url,
      outlookWindows: codesByVersion,
      notes: feature.notes ?? null,
      notesByNum: feature.notes_by_num ?? null,
    });
  }

  gimmicks.sort((a, b) => a.slug.localeCompare(b.slug));

  await writeFile(
    OUT_PATH,
    JSON.stringify(
      {
        source: DATA_URL,
        fetchedAt: new Date().toISOString(),
        count: gimmicks.length,
        gimmicks,
      },
      null,
      2,
    ) + "\n",
  );

  console.log(`Wrote ${gimmicks.length} gimmicks to ${path.relative(process.cwd(), OUT_PATH)}`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
